-- =====================================================================
-- SmarterVote.ca — expansion seed: issue taxonomy for in-depth municipalities
--
-- The same 18-issue taxonomy for each of the 18 in-depth municipalities.
--
-- FINAL taxonomy per Andreas 2026-10-17. Huntsville's live issue rows keep
-- the old slugs (how-council-works, economy-and-downtown,
-- healthcare-and-hospital, parks-and-trails) -- not renamed here.
-- Display names and voter questions follow the site's civic tone (cf.
-- 04_issues.sql): plain language, the question a voter actually asks.
-- trustee-role and student-wellbeing are for school board races only.
--
-- Run AFTER 25. Idempotent: on conflict (municipality_id, slug) do nothing.
-- =====================================================================

begin;

insert into issues
    (municipality_id, name, slug, voter_question, description, sort_order)
select m.id, v.name, v.slug, v.voter_question, v.description, v.sort_order
from (values
-- ---- Bracebridge ----
    ('bracebridge', 'Housing', 'housing', 'Will I be able to afford to live here?', 'Rents, home prices and new supply -- plus homelessness and encampments, and short-term rentals. Absorbs the old homelessness-and-encampments issue: shelter capacity, outreach, enforcement, and what the municipality controls versus the province.', 1),
    ('bracebridge', 'Taxes & spending', 'taxes-and-spending', 'What happens to my tax bill, and where does the money go?', 'The municipal levy, what drives it up, and what the candidate would cut, protect or spend more on. The most universal issue in any local election.', 2),
    ('bracebridge', 'Emergency services', 'emergency-services', 'When I call for help, will it come fast enough?', 'Police, fire and paramedics together: response times, station and detachment coverage, budgets and priorities, and how the candidate balances enforcement with prevention. Absorbs the old policing issue.', 3),
    ('bracebridge', 'Transit', 'transit', 'Can I get where I need to go without driving?', 'Bus routes and frequency, fares, paratransit, and whether transit reaches the places people actually go -- jobs, schools, medical appointments.', 4),
    ('bracebridge', 'Government', 'government', 'Will decisions be made in the open, and will anyone answer for them?', 'Transparency, public consultation, conflicts of interest, and how the candidate would run meetings and make decisions once elected. Renamed from how-council-works.', 5),
    ('bracebridge', 'Roads & infrastructure', 'roads-and-infrastructure', 'Will the things I use every day actually get fixed?', 'Roads, sidewalks, bridges, snow clearing, water and wastewater. The unglamorous work a municipality is mostly judged on.', 6),
    ('bracebridge', 'Economy', 'economy', 'Will our main streets and local jobs thrive?', 'Downtown vitality, small business support, attracting employers, and what the town offers beyond bedroom-community status. Renamed from economy-and-downtown.', 7),
    ('bracebridge', 'Environment', 'environment', 'Is the candidate protecting the nature we live in?', 'Tree canopy, shoreline and greenspace protection, climate adaptation, and balancing growth with the natural assets that define the area.', 8),
    ('bracebridge', 'Healthcare', 'healthcare', 'Will there be a doctor and a hospital when we need one?', 'Physician recruitment, hospital funding advocacy, long-term care. Mostly provincial files where the municipality lobbies, partners and plans. Renamed from healthcare-and-hospital.', 9),
    ('bracebridge', 'Growth & development', 'growth-and-development', 'How fast should we grow, and who decides what gets built where?', 'Official plans, intensification versus sprawl, development charges, and whether growth pays for itself.', 10),
    ('bracebridge', 'Social & community services', 'social-and-community-services', 'Who looks after the most vulnerable residents?', 'Food banks, shelters, seniors and youth programs -- often delivered with the upper tier or non-profits, steered by council funding choices.', 11),
    ('bracebridge', 'Active transportation', 'active-transportation', 'Can I walk and bike safely around town?', 'Sidewalks, bike lanes, trails as transportation, safe routes to school and to transit. Renamed from parks-and-trails -- note the narrower focus: getting around under your own power, not arenas and pools.', 12),
    ('bracebridge', 'Arts & culture', 'arts-and-culture', 'Does the candidate value what makes this place feel alive?', 'Festivals, public art, heritage, and grants for the groups that give a town its identity.', 13),
    ('bracebridge', 'Data centres', 'data-centres', 'Should energy-hungry data centres be welcomed here?', 'Tax revenue and jobs versus electricity demand, water use and noise. A live file in several municipalities this cycle.', 14),
    ('bracebridge', 'Water & waste', 'water-and-waste', 'Is our drinking water safe and our waste handled?', 'Treatment plants, wells, garbage and recycling. Invisible until they fail -- and then the only thing that matters.', 15),
    ('bracebridge', 'Bylaw enforcement', 'bylaw-enforcement', 'Are the rules fair, and are they actually enforced?', 'Noise, property standards, short-term rentals, parking. Where municipal rules meet daily life.', 16),
    ('bracebridge', 'What a trustee actually does', 'trustee-role', 'Does the candidate understand the trustee job?', 'Trustees govern a school board, not a school: budgets, policy, and hiring the director. For school board races only.', 17),
    ('bracebridge', 'Student wellbeing and learning', 'student-wellbeing', 'Will kids be safe, supported and learning well?', 'Mental health supports, special education, bullying, and achievement gaps. For school board races only.', 18),
